-- Synthetic, written by hand for the identity and sequence mappings to PostgreSQL (see ../README.md). Not tool output.

  CREATE TABLE "APP"."ACCOUNTS"
   (	"ACCOUNT_ID" NUMBER(*,0) GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 393 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,
	"NAME" VARCHAR2(100 CHAR) NOT NULL ENABLE,
	 CONSTRAINT "ACCOUNTS_PK" PRIMARY KEY ("ACCOUNT_ID")
  USING INDEX  ENABLE
   ) SEGMENT CREATION IMMEDIATE
  TABLESPACE "USERS" ;

  CREATE TABLE "APP"."TICKETS"
   (	"TICKET_ID" INTEGER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 3 START WITH 7 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,
	"TITLE" VARCHAR2(100 CHAR),
	 CONSTRAINT "TICKETS_PK" PRIMARY KEY ("TICKET_ID")
  USING INDEX  ENABLE
   ) SEGMENT CREATION IMMEDIATE
  TABLESPACE "USERS" ;

   CREATE SEQUENCE  "APP"."NOTES_SEQ"  MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  GLOBAL ;

  CREATE TABLE "APP"."NOTES"
   (	"NOTE_ID" NUMBER(*,0) NOT NULL ENABLE,
	"BODY" VARCHAR2(200 CHAR),
	 CONSTRAINT "NOTES_PK" PRIMARY KEY ("NOTE_ID")
  USING INDEX  ENABLE
   ) SEGMENT CREATION IMMEDIATE
  TABLESPACE "USERS" ;

  CREATE OR REPLACE EDITIONABLE TRIGGER "APP"."NOTES_BI"
BEFORE INSERT ON "APP"."NOTES" FOR EACH ROW
BEGIN
  SELECT "APP"."NOTES_SEQ".NEXTVAL INTO :NEW."NOTE_ID" FROM dual;
END;
/
